const FSA_ENGLISH_LEXICAL_ALPHABET = "abcdefghijklmnopqrstuvwxyz";
const FSA_PERSIAN_LEXICAL_ALPHABET = "ءآأؤئابةتثجحخدذرزسشصضطظعغفقلمنهؤپچژکگی";

function normalizeFsaEnglishLexeme(value) {
    return String(value ?? '')
        .toLowerCase()
        .replace(/[^a-z]/gu, '');
}

function normalizeFsaPersianLexeme(value) {
    return String(value ?? '')
        .normalize('NFC')
        .replace(/[ًٌٍَُِّْـ]/gu, '')
        .replaceAll('ي', 'ی')
        .replaceAll('ى', 'ی')
        .replaceAll('ك', 'ک')
        .replaceAll('\u200c', '')
        .replace(/[^\u0621-\u06CC]/gu, '');
}

function fsaLexicalHashA(value) {
    let hash = 0x811c9dc5;

    for (const char of String(value ?? '')) {
        hash ^= char.codePointAt(0);
        hash = Math.imul(
            hash,
            0x01000193
        );
    }

    return hash >>> 0;
}

function fsaLexicalHashB(value) {
    let hash = 0x9e3779b9;

    for (const char of String(value ?? '')) {
        hash ^= char.codePointAt(0);
        hash = Math.imul(
            hash,
            0x01000193
        );
        hash ^= hash >>> 13;
    }

    return hash >>> 0;
}

function fsaLexicalHash(value) {
    return fsaLexicalHashA(value);
}

function fsaLexicalKey(value) {
    const first =
        fsaLexicalHashA(value) &
        FSA_LEXICAL_KEY_MASK_26;

    const second =
        fsaLexicalHashB(value) &
        FSA_LEXICAL_KEY_MASK_26;

    return (
        first *
        FSA_LEXICAL_KEY_SHIFT_26
    ) + second;
}

function fsaHasLexicalKey(
    sortedKeys,
    key
) {
    let low = 0;
    let high =
        sortedKeys.length - 1;

    while (low <= high) {
        const mid =
            (low + high) >> 1;

        const current =
            sortedKeys[mid];

        if (current === key) {
            return true;
        }

        if (current < key) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return false;
}

function isFsaKnownEnglishLexeme(value) {
    const normalized =
        normalizeFsaEnglishLexeme(
            value
        );

    if (normalized.length < 2) {
        return false;
    }

    return fsaHasLexicalKey(
        FSA_ENGLISH_LEXICAL_KEYS,
        fsaLexicalKey(normalized)
    );
}

function isFsaKnownPersianLexeme(value) {
    const normalized =
        normalizeFsaPersianLexeme(
            value
        );

    if (normalized.length < 2) {
        return false;
    }

    return fsaHasLexicalKey(
        FSA_PERSIAN_LEXICAL_KEYS,
        fsaLexicalKey(normalized)
    );
}
